import json,os,collections
rows=[json.loads(l) for l in open('/workspace/observed_run/experiment_logs/rollout_records.jsonl')]
by={}
for r in rows:
    for t in r['trial_dirs']: by[os.path.basename(t)]=r

def classify(r):
    ts=set()
    for mm in r['tito_session_mismatch']:
        if isinstance(mm,dict): mm=[mm]
        for m in mm: ts.add(m['type'])
    return tuple(sorted(ts))

eq=collections.Counter(); details=[]
for name,r in sorted(by.items()):
    f=f'/workspace/observed_run/harbor_trials/{name}/agent/mini-swe-agent.txt'
    txt=open(f,errors='replace').read()
    a=txt.count('Tool call error:'); b=txt.count('reached the output token limit'); fe=a+b
    extra=r['leaf_count']-1
    rel = 'fe' if extra==fe else ('fe-1' if extra==fe-1 else 'other')
    eq[rel]+=1
    repeated = 'RepeatedFormatError' in txt
    if rel!='fe' or 'special_token_count' in classify(r):
        details.append((name,r['sample_index'],r['leaf_count'],extra,fe,a,b,rel,repeated,r['exit_statuses'],classify(r)))
print("relation counts:",dict(eq))
print("Exceptions / structural-mismatch trials:")
for d in details: print(d)
EOF

