import json, re
recs=[json.loads(l) for l in open('experiment_logs/rollout_records.jsonl')]
shown=0
for r in recs:
    for li,leaf in enumerate(r.get('tito_session_mismatch') or []):
        for seg in leaf:
            if seg.get('type')=='special_token_count' and shown<1:
                print('record sample_index', r['sample_index'], 'leaf', li, 'segment_index', seg['segment_index'])
                print('detail:', seg.get('detail'))
                for name in ('expected_text','actual_text'):
                    t=seg[name]
                    print(name, 'len', len(t))
                    print('  tail:', t[-300:])
                print()
                shown+=1
# summarize segment-count delta and tail special token
deltas={}
for r in recs:
    for leaf in r.get('tito_session_mismatch') or []:
        for seg in leaf:
            if seg.get('type')=='special_token_count':
                def nseg(t): return len(re.findall(r'\[<\|im_start\|>\]', t))
                e,a=seg['expected_text'], seg['actual_text']
                d=(nseg(e),nseg(a), e.rstrip().endswith('[<|im_end|>]'), a.rstrip().endswith('[<|im_end|>]'))
                deltas[d]=deltas.get(d,0)+1
print('segment count / tail-end patterns:', deltas)
# assistant_text detail examples
c=0
for r in recs:
    for leaf in r.get('tito_session_mismatch') or []:
        for seg in leaf:
            if seg.get('type')=='assistant_text' and c<2:
                print('assistant_text detail:', seg.get('detail'))
                c+=1
